+// Wire-contract tests for the OpenAI (Responses) provider, exercised through
+// the *real* `@ai-sdk/openai` adapter: each case streams one turn through the
+// gateway with a stubbed fetch and asserts on the request body.
+//
+// Reasoning "off" travels as the AI SDK's portable `reasoning: "none"`, which
+// this adapter translates per model. Models that cannot turn reasoning off
+// (gpt-6-astra advertises only low through max) must not receive
+// `effort: "none"`; models that can (gpt-5.5, gpt-6-sol) still must.
+import type { GatewayStreamRequest } from "@cline/shared";
+import { describe, expect, it } from "vitest";
+import { createGateway } from "../gateway";
+
+async function wireBody(input: {
+	modelId: string;
+	reasoning?: GatewayStreamRequest["reasoning"];
+	modelTools?: GatewayStreamRequest["modelTools"];
+}): Promise<Record<string, unknown>> {
+	let body: Record<string, unknown> | undefined;
+	const fetchStub = (async (_input, init) => {
+		body = JSON.parse((init?.body as string) ?? "{}");
+		return new Response(JSON.stringify({ error: { message: "stub" } }), {
+			status: 400,
+			headers: { "content-type": "application/json" },
+		});
+	}) as typeof fetch;
+	const gateway = createGateway({
+		providerConfigs: [
+			{ providerId: "openai-native", apiKey: "test-key", fetch: fetchStub },
+		],
+	});
+	for await (const _event of await gateway.stream({
+		providerId: "openai-native",
+		modelId: input.modelId,
+		reasoning: input.reasoning,
+		modelTools: input.modelTools,
+		messages: [
+			{
+				id: "m1",
+				role: "user",
+				content: [{ type: "text", text: "hi" }],
+				createdAt: 0,
+			},
+		],
+	})) {
+		// drain
+	}
+	if (!body) {
+		throw new Error("the stubbed fetch was never called");
+	}
+	return body;
+}
+
+describe("OpenAI Responses wire contract", () => {
+	it("does not ask a model without a reasoning-off setting to turn reasoning off", async () => {
+		const body = await wireBody({
+			modelId: "gpt-6-astra",
+			reasoning: { enabled: false },
+		});
+
+		expect(
+			(body.reasoning as { effort?: string } | undefined)?.effort,
+		).not.toBe("none");
+	});

